--

CREATE TABLE public.user_obligations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    institution_id uuid,
    student_id uuid,
    independent_user_id uuid,
    source text DEFAULT 'self'::text NOT NULL,
    kind text NOT NULL,
    title text NOT NULL,
    due_at timestamp with time zone NOT NULL,
    all_day boolean DEFAULT false NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    deep_link text,
    done_at timestamp with time zone,
    idempotency_key text,
    version integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT user_obligations_kind_check CHECK ((kind = ANY (ARRAY['study_block'::text, 'mock'::text, 'review'::text, 'custom'::text]))),
    CONSTRAINT user_obligations_owner_xor CHECK ((num_nonnulls(student_id, independent_user_id) = 1)),
    CONSTRAINT user_obligations_source_check CHECK ((source = ANY (ARRAY['self'::text, 'plan_engine'::text]))),
    CONSTRAINT user_obligations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'done'::text, 'dismissed'::text, 'expired'::text]))),
    CONSTRAINT user_obligations_title_check CHECK (((char_length(title) >= 1) AND (char_length(title) <= 120)))
);

ALTER TABLE ONLY public.user_obligations FORCE ROW LEVEL SECURITY;


ALTER TABLE public.user_obligations OWNER TO macbook;

