CREATE TABLE public.visual_canvases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    institution_id uuid,
    student_id uuid,
    independent_user_id uuid,
    title text NOT NULL,
    archetype text NOT NULL,
    graph jsonb NOT NULL,
    schema_version integer DEFAULT 1 NOT NULL,
    origin text NOT NULL,
    source_id uuid,
    topic_id uuid,
    source_session_id uuid,
    legacy_artifact_id uuid,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'ready'::text NOT NULL,
    deleted_at timestamp with time zone,
    node_count integer DEFAULT 0 NOT NULL,
    source_meta jsonb,
    debate_id uuid,
    CONSTRAINT visual_canvases_archetype_ck CHECK ((archetype = ANY (ARRAY['mind_map'::text, 'flowchart'::text, 'cycle'::text, 'timeline'::text, 'hierarchy'::text, 'comparison'::text]))),
    CONSTRAINT visual_canvases_node_count_ck CHECK ((node_count >= 0)),
    CONSTRAINT visual_canvases_origin_ck CHECK ((origin = ANY (ARRAY['prompt'::text, 'library_source'::text, 'learn_topic'::text, 'learn_session'::text, 'memory'::text, 'legacy'::text, 'debate_clash'::text]))),
    CONSTRAINT visual_canvases_status_ck CHECK ((status = ANY (ARRAY['generating'::text, 'ready'::text, 'failed'::text]))),
    CONSTRAINT visual_canvases_subject_ck CHECK ((((student_id IS NOT NULL) AND (independent_user_id IS NULL) AND (institution_id IS NOT NULL)) OR ((student_id IS NULL) AND (independent_user_id IS NOT NULL) AND (institution_id IS NULL))))
);

